@include('public.business.admin.configurations._workspace_styles')
<style>
.ret-page{--rp-bg:#f7f8fc;--rp-panel:#fff;--rp-border:#e2e7ef;--rp-ink:#172135;--rp-muted:#6d778a;--rp-primary:#5652cf;display:grid;grid-template-columns:276px minmax(0,1fr);min-height:calc(100vh - 76px);background:var(--rp-bg);color:var(--rp-ink)}
.ret-page .workspace-sidebar{--ws-panel:var(--rp-panel);--ws-bg:var(--rp-bg);--ws-text:var(--rp-ink);--ws-muted:var(--rp-muted);--ws-line:var(--rp-border)}
.ret-page .workspace-content{padding:24px;min-width:0;max-width:none}.ret-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px;flex-wrap:wrap}.ret-title h1{font-size:23px;line-height:1.35;margin:0}.ret-title p{color:var(--rp-muted);font-size:12px;margin-top:5px}.ret-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.ret-card{background:var(--rp-panel);border:1px solid var(--rp-border);border-radius:13px;padding:20px;margin-bottom:16px;min-width:0}.ret-btn{display:inline-flex;align-items:center;justify-content:center;background:var(--rp-primary);color:#fff!important;padding:9px 14px;border-radius:8px;font-size:12px;font-weight:700;border:1px solid transparent;cursor:pointer}.ret-btn.alt{background:var(--rp-panel);color:var(--rp-ink)!important;border-color:var(--rp-border)}.ret-btn.danger{background:#b93a51}.ret-input,.ret-page input,.ret-page select,.ret-page textarea{max-width:100%;font-family:inherit}.ret-input{border:1px solid var(--rp-border);background:var(--rp-panel);color:var(--rp-ink);border-radius:8px;padding:10px;font-size:12px;width:100%;min-height:37px}.ret-input:focus{outline:2px solid #9b99fa}.ret-grid{display:grid;grid-template-columns:repeat(3,minmax(160px,1fr));gap:13px}.ret-field label{display:block;font-weight:700;font-size:11px;margin:0 0 6px}.ret-help{font-size:11px;color:var(--rp-muted);margin:8px 0}.ret-table-wrap{width:100%;overflow:auto}.ret-table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}.ret-table th,.ret-table td{padding:10px 11px;border-bottom:1px solid var(--rp-border);text-align:left}.ret-table th{font-size:11px;color:var(--rp-muted)}.ret-table thead .ret-input{min-width:87px;padding:7px;font-size:11px}.ret-table td{color:var(--rp-ink)}.ret-table tr:hover{background:rgba(120,130,160,.04)}.ret-toolbar{display:flex;gap:9px;margin-bottom:14px;align-items:center;flex-wrap:wrap}.ret-toolbar .ret-input{max-width:300px}.ret-toast{padding:12px;background:#eaf8f0;color:#176d47;border-radius:9px;margin-bottom:12px}.ret-error{padding:12px;background:#fdf0f1;color:#a2323b;border-radius:9px;margin-bottom:12px}.ret-cart-row{display:grid;grid-template-columns:minmax(180px,3fr) 100px 100px 46px;gap:8px;margin:9px 0}.ret-cart-row.purchase{grid-template-columns:minmax(180px,3fr) 100px 110px 46px}.ret-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.ret-kpi{background:var(--rp-panel);border:1px solid var(--rp-border);padding:19px;border-radius:12px}.ret-kpi strong{display:block;font-size:19px;margin:6px 0}.ret-divider{border:0;border-top:1px solid var(--rp-border);margin:18px 0}.ret-product-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(185px,1fr));gap:10px}.ret-product-choice{text-align:left;border:1px solid var(--rp-border);background:var(--rp-panel);color:var(--rp-ink);padding:15px;border-radius:11px;cursor:pointer}.ret-product-choice small{display:block;color:var(--rp-muted);margin:5px 0}.ret-product-choice:hover{border-color:var(--rp-primary)}.ret-mobile-nav{display:none}
html[data-theme=dark] .ret-page{--rp-bg:#111827;--rp-panel:#1d2738;--rp-border:#344258;--rp-ink:#f0f3fa;--rp-muted:#abb6c9;--rp-primary:#716df0}html[data-theme=dark] .ret-toast{background:#173a2b;color:#a0f2c1}html[data-theme=dark] .ret-error{background:#3c2630;color:#f7abb4}
@media(max-width:1050px){.ret-page{display:block}.ret-page .workspace-sidebar{position:fixed;top:0;left:0;width:min(310px,86vw);height:100dvh;z-index:220;transform:translateX(-105%);transition:transform .25s}.ws-sidebar-open .ret-page .workspace-sidebar{transform:translateX(0)}.ret-mobile-nav{display:inline-flex}.ret-page .workspace-content{padding:17px}}
@media(max-width:700px){.ret-grid{grid-template-columns:1fr}.ret-kpis{grid-template-columns:repeat(2,1fr)}.ret-cart-row,.ret-cart-row.purchase{grid-template-columns:1fr 80px 85px 36px}.ret-title h1{font-size:20px}}
</style>

<script>document.addEventListener('DOMContentLoaded',()=>{const buttons=[...document.querySelectorAll('[data-ws-sidebar-toggle]')],overlay=document.querySelector('[data-ws-sidebar-overlay]');function toggle(open){document.body.classList.toggle('ws-sidebar-open',open);buttons.forEach(b=>b.setAttribute('aria-expanded',String(open)))}buttons.forEach(b=>b.onclick=()=>toggle(!document.body.classList.contains('ws-sidebar-open')));if(overlay)overlay.onclick=()=>toggle(false);document.addEventListener('keydown',e=>{if(e.key==='Escape')toggle(false)});});</script>
